window.NOTES={"version":50,"chapters":[{"number":1,"title":"信息技术与计算机文化","summary":"计算机发展、信息表示、硬件、软件与计算机系统的基础概念。","sections":[{"id":"1.1","title":"信息与信息技术"},{"id":"1.2","title":"计算机技术概论"},{"id":"1.3","title":"计算机中信息的表示"},{"id":"1.4","title":"计算机系统"},{"id":"1.5","title":"微型计算机系统"}]},{"number":2,"title":"Windows 10 操作系统","summary":"操作系统特征、Windows界面、文件管理、系统设置与维护。","sections":[{"id":"2.1","title":"操作系统概述"},{"id":"2.2","title":"Windows 10 基础"},{"id":"2.3","title":"文件和文件夹管理"},{"id":"2.4","title":"控制面板"},{"id":"2.5","title":"Windows 10 的系统维护"},{"id":"2.6","title":"Windows 10 的实用工具"}]},{"number":3,"title":"字处理软件 Word 2016","summary":"文档编辑、格式排版、表格、图文混排与长文档功能。","sections":[{"id":"3.1","title":"使用 Office 2016 应用程序"},{"id":"3.2","title":"Word 2016 的基本操作"},{"id":"3.3","title":"文档格式化与排版"},{"id":"3.4","title":"表格制作"},{"id":"3.5","title":"图文混排"},{"id":"3.6","title":"文档的保护与打印"},{"id":"3.7","title":"Word 2016 的高级应用"}]},{"number":4,"title":"电子表格系统 Excel 2016","summary":"工作表操作、公式与函数、格式化、数据处理和图表。","sections":[{"id":"4.1","title":"Excel 2016 概述"},{"id":"4.2","title":"Excel 2016 的基本操作"},{"id":"4.3","title":"Excel 公式与函数"},{"id":"4.4","title":"格式化工作表"},{"id":"4.5","title":"数据处理"},{"id":"4.6","title":"使用图表"}]},{"number":5,"title":"演示文稿软件 PowerPoint 2016","summary":"幻灯片组织、外观、动画、切换与放映设置。","sections":[{"id":"5.1","title":"PowerPoint 2016 基础"},{"id":"5.2","title":"幻灯片页面设计"},{"id":"5.3","title":"幻灯片页面外观的修饰"},{"id":"5.4","title":"动画效果和动作设置"},{"id":"5.5","title":"播放和打印演示文稿"},{"id":"5.6","title":"演示文稿的其他功能"}]},{"number":6,"title":"计算机网络及网页制作","summary":"网络结构、Internet应用、HTML、网页与信息检索。","sections":[{"id":"6.1","title":"计算机网络概述"},{"id":"6.2","title":"计算机网络系统"},{"id":"6.3","title":"Internet 基础和应用"},{"id":"6.4","title":"网页、网页制作及 HTML 简介"},{"id":"6.5","title":"信息检索"}]},{"number":7,"title":"数字多媒体技术基础","summary":"多媒体特征、媒体元素、图像格式、颜色和视频。","sections":[{"id":"7.1","title":"数字多媒体技术概述"},{"id":"7.2","title":"数字多媒体系统组成及常用软件"},{"id":"7.3","title":"常用多媒体制作软件"}]},{"number":8,"title":"信息安全","summary":"安全属性、恶意软件、防火墙、密码技术和信息伦理。","sections":[{"id":"8.1","title":"信息安全概述"},{"id":"8.2","title":"计算机病毒"},{"id":"8.3","title":"防火墙"},{"id":"8.4","title":"Windows 10 操作系统安全"},{"id":"8.5","title":"信息伦理"}]},{"number":9,"title":"信息技术前沿","summary":"虚拟现实、云计算、物联网、区块链与人工智能。","sections":[{"id":"9.1","title":"虚拟现实和增强现实"},{"id":"9.2","title":"云计算和高性能计算"},{"id":"9.3","title":"物联网技术"},{"id":"9.4","title":"大数据技术"},{"id":"9.5","title":"区块链技术"},{"id":"9.6","title":"人工智能"},{"id":"9.7","title":"量子信息"},{"id":"9.8","title":"元宇宙"}]},{"number":10,"title":"数据库技术基础","summary":"关系数据库、数据库管理系统、关系运算、SQL与NoSQL。","sections":[{"id":"10.1","title":"数据库技术基础"},{"id":"10.2","title":"数据库管理系统"},{"id":"10.3","title":"数据库设计与 NoSQL"}]},{"number":11,"title":"计算思维","summary":"计算思维、算法表示、算法特征和基本控制结构。","sections":[{"id":"11.1","title":"计算思维"},{"id":"11.2","title":"计算思维与算法"},{"id":"11.3","title":"算法的控制结构"},{"id":"11.4","title":"面向对象程序设计"},{"id":"11.5","title":"基础算法设计思想"}]}],"notes":[{"q":29,"chapter":9,"section":"9.1","type":"多选","topic":"虚拟现实","title":"虚拟现实的核心特征与判断边界","trigger":"两道题从应用辨析和特征选择考查虚拟现实。","conclusion":"VR的核心是计算机生成的三维虚拟环境，以及沉浸性、交互性、想象性和多感知体验。","points":["沉浸性让用户产生置身环境的感受，交互性让系统根据动作反馈。","普通3D游戏或三维电影不能仅凭“3D”自动认定为VR。","美容预览可能是图像处理或增强现实，需看是否建立可交互虚拟环境。","VR以虚拟环境为主；AR把数字信息叠加到现实环境并与之关联。两者都可能具有交互和临场体验，不能笼统断言AR总比VR更沉浸或更独立。"],"boundary":"判断VR不能只看画面是否立体，还要检查沉浸、交互和环境生成条件。","id":"merged-18","sources":[{"year":2020,"q":29,"type":"多选"},{"year":2026,"q":29,"type":"多选"},{"year":2021,"q":29,"type":"多选","page":5}],"keys":["2020-29","2026-29","2021-29"],"related":[{"id":"y2026q4","label":"多媒体强调集成、交互与实时处理","reason":"VR中的多感知、交互和实时反馈建立在多媒体能力上，但判断VR还须确认可交互的虚拟环境。"},{"id":"y2024q20","label":"沉浸与互操作不会自动消除隐私风险","reason":"沉浸体验需要感知用户动作和环境，进一步查看这些数据采集为何带来隐私与治理问题。"}]},{"q":20,"chapter":9,"section":"9.2","type":"单选","topic":"云计算","title":"云计算强调按需资源、资源池化、弹性与分层服务","trigger":"真题从临时取得算力存储、云特征、远程租用和IaaS/PaaS/SaaS考查云计算。","conclusion":"云计算通过网络按需提供可度量、可快速扩展与释放的资源，并按责任边界形成IaaS、PaaS和SaaS等服务模型。","points":["IaaS提供计算、存储、网络等基础资源，用户可管理操作系统和应用；PaaS提供开发运行平台，用户部署自己的应用；SaaS直接提供现成应用，用户主要使用和配置应用。","资源池把资源统一组织并按需分配，快速弹性使资源随负载增减。例如报名高峰增加计算资源，峰后释放；可度量则让双方能统计和管理使用量。","典型特征是按需自助、广泛网络访问、资源池化、快速弹性、可度量服务。仅远程控制一台配置固定的电脑，并不能由“远程”二字推出它具备这些特征。","公有云面向公众开放使用；私有云供一个组织专用。私有云可由本组织或第三方管理，可部署在组织内部或外部，关键是专用范围。","人少、场地小、数据增长快时可考虑云存储，按需求扩容并减少自建机房投入；仍须评估持续费用、网络依赖、备份、权限和服务商责任，不能理解为无需管理或必然最便宜。"],"boundary":"云服务不是天然更便宜或绝对安全，安全、容量和费用仍需共同治理。","id":"y2026q39","sources":[{"year":2023,"q":20,"type":"单选"},{"year":2025,"q":17,"type":"单选"},{"year":2025,"q":45,"type":"填空"},{"year":2026,"q":39,"type":"判断"},{"year":2022,"q":20,"type":"单选"},{"year":2021,"q":60,"type":"分析","page":10}],"keys":["2023-20","2025-17","2025-45","2026-39","2022-20","2021-60"],"related":[{"id":"merged-19","label":"物联网的感知、连接与数据处理","reason":"物联网可把集中存储分析交给云，也可在边缘处理；云服务并不意味着全部设备数据都必须上云。"},{"id":"y2026q45","label":"算力表示计算设备处理数据的能力","reason":"云可按需提供计算资源，但实际算力表现仍受网络、存储、软件栈和调度影响。"}],"pointGroups":[{"title":"服务模型、资源弹性与识别条件","indices":[0,1,2]},{"title":"部署范围与选用时的管理责任","indices":[3,4]}],"comparison":{"headers":["服务模型","使用者的典型工作","辨认线索"],"rows":[["IaaS","配置虚拟机并安装系统、应用","租用基础计算资源"],["PaaS","提交代码、部署和管理自己的应用","使用现成运行平台"],["SaaS","直接登录并使用在线应用","使用现成软件功能"]]}},{"q":30,"chapter":9,"section":"9.3","type":"多选","topic":"物联网","title":"物联网的感知、连接与数据处理","trigger":"真题从三层架构、识别定位、云平台、应用识别和海量数据处理考查物联网。","conclusion":"物联网围绕物体建立感知、连接、数据交换和智能服务；传感器、RFID和定位技术采集状态，网络与云边平台完成传输处理。","points":["大量联网设备是大数据的重要来源。","网络层传输数据，应用层形成面向场景的服务。","边缘计算可降低延迟和带宽压力，云平台适合集中存储、分析和管理。","RFID利用射频信号识别标签，是物联网常见感知技术；不同类型标签的供电、距离和读写能力不同。","传感器把温度、压力、光等被测量转换为可用信号，属于物联网感知环节；采集、联网与应用分析是不同分工。","常用三层架构的完整名称：感知层、网络层、应用层。传感器/RFID归感知层，传输归网络层，具体服务归应用层。","以温室为例：传感器采到32℃，网络把数值送到控制程序；程序按设定阈值判断过热，再发送开风扇指令。传感器负责取得状态，网络负责传送，应用负责规则与服务，执行器把控制结果作用到环境。"],"boundary":"物联网强调物体通过网络交换数据并形成应用；设备可经网关联网，也可在局域网内完成部分服务，不要求每个设备都直接接入公网或把全部数据上传云端。","id":"merged-19","sources":[{"year":2023,"q":30,"type":"多选"},{"year":2024,"q":50,"type":"填空"},{"year":2026,"q":19,"type":"单选"},{"year":2026,"q":40,"type":"判断"},{"year":2022,"q":40,"type":"判断"},{"year":2021,"q":40,"type":"填空","page":6}],"keys":["2023-30","2024-50","2026-19","2026-40","2022-40","2021-40"],"related":[{"id":"y2026q39","label":"云计算强调按需资源、资源池化、弹性与分层服务","reason":"云平台可承接集中存储和分析，服务模型与弹性说明这些资源如何按需提供和管理。"},{"id":"y2025q18","label":"大数据的规模、速度、多样性与价值密度要按材料判断","reason":"大量传感器和联网设备可持续产生多来源数据，但是否体现大数据特征还要看规模、速度和类型。"},{"id":"merged-13","label":"TCP/IP四层模型与OSI七层模型的对应关系","reason":"物联网三层按感知、传输和服务分工；TCP/IP分层按通信协议职责划分，两个模型不能只按层名机械对应。"}],"pointGroups":[{"title":"感知、网络与应用的三层分工","indices":[1,3,4,5,6]},{"title":"数据来源与云边处理取舍","indices":[0,2]}]},{"q":50,"chapter":9,"section":"9.4","type":"填空","topic":"大数据特征","title":"大数据的规模、速度、多样性与价值密度要按材料判断","trigger":"真题从多种数据格式和海量视频中的少量有效片段考查大数据特征。","conclusion":"文本、图像、音视频和日志并存体现多样性Variety；海量数据中有用信息占比较低体现低价值密度。","points":["Volume强调规模大，Velocity强调产生和处理速度快。","Variety强调结构化、半结构化和非结构化数据并存。","价值密度低不等于最终提取出的信息没有价值。","广告推荐、交通分析和城市运行分析可利用大规模多来源数据；单次扫描条形码只是识别行为，不能仅凭“有码”认定为大数据。"],"boundary":"同一材料可能同时具有多个V；题目突出“种类/格式”时判断多样性，突出“有用占比”时判断价值密度。","id":"y2025q18","sources":[{"year":2023,"q":50,"type":"填空"},{"year":2025,"q":18,"type":"单选"},{"year":2022,"q":30,"type":"多选"}],"keys":["2023-50","2025-18","2022-30"],"related":[{"id":"merged-19","label":"物联网的感知、连接与数据处理","reason":"从传感器、RFID和联网设备理解大数据的一类来源，也辨认单次识别为何不足以说明大数据。"},{"id":"y2025q40","label":"推荐系统发现相关性不等于证明因果关系","reason":"从多来源数据提取有用模式不代表获得因果解释，规模扩大也不能自动消除偏差。"},{"id":"y2026q12","label":"NoSQL按数据模型与访问需求选型","reason":"多样的数据与查询需求会影响数据库选型，不能仅因数据量大就默认使用某一种NoSQL产品。"}]},{"q":40,"chapter":9,"section":"9.4","type":"判断","topic":"相关与因果","title":"推荐系统发现相关性不等于证明因果关系","trigger":"题目以购买一本书后收到相似推荐为例考查大数据时代的相关关系。","conclusion":"推荐系统可根据共现、相似用户或行为模式发现相关性，但相关性本身不能证明一个行为导致另一个结果。","points":["协同过滤常利用“相似用户也喜欢”的模式。","混杂因素可能同时影响两个变量。","因果判断通常需要实验设计、自然实验或更严格的统计证据。","大数据场景常重视更广数据范围、及时处理和相关模式，但不意味着必须不用抽样、不求精度或不研究因果；数据规模大也不能自动消除偏差。"],"boundary":"推荐有效只说明相关模式有预测价值，不代表系统已经解释真实原因。","id":"y2025q40","sources":[{"year":2025,"q":40,"type":"判断"},{"year":2021,"q":19,"type":"单选","page":4}],"keys":["2025-40","2021-19"],"related":[{"id":"y2025q18","label":"大数据的规模、速度、多样性与价值密度要按材料判断","reason":"大规模多来源数据提供模式发现的材料，但有用信息占比、样本偏差与因果证据仍须分别判断。"},{"id":"y2020q30","label":"人工智能从感知、学习和推理支持智慧应用","reason":"推荐属于学习、预测等智慧应用的语境；预测有效不等于模型已经说明现实原因。"}]},{"q":19,"chapter":9,"section":"9.5","type":"单选","topic":"区块链","title":"区块链结构、共识、可追溯性与信任边界","trigger":"真题从账本结构、多节点共识、难篡改、可追溯和缺少单一信任中心的协作考查区块链。","conclusion":"区块链是以密码学方式连接并由多方共同维护的分布式账本；它可降低多方协作中的部分信任成本，但不消除治理责任。","points":["哈希连接和共识机制使历史记录难以被单方静默篡改。","公有链记录通常较透明，许可链可限制参与和可见范围。","链上输入仍可能错误，隐私、法律和线下履约仍需制度与技术保障。","数字签名使用非对称密码：签名者用私钥签名，接收方用相应公钥验证。哈希摘要本身不等于数字签名；签名用于验证来源与完整性，不等于加密内容保密。"],"boundary":"“难篡改”不等于绝对不可篡改，“去中心化”也不等于完全匿名或无需信任。","id":"merged-17","sources":[{"year":2020,"q":19,"type":"单选"},{"year":2023,"q":40,"type":"判断"},{"year":2024,"q":40,"type":"判断"},{"year":2025,"q":19,"type":"单选"},{"year":2026,"q":20,"type":"单选"}],"keys":["2020-19","2023-40","2024-40","2025-19","2026-20"],"related":[{"id":"merged-15","label":"加密、解密、公钥与私钥","reason":"哈希连接与数字签名承担不同工作，签名需检查私钥、公钥归属及消息完整性，不能与保密加密混同。"},{"id":"y2024q20","label":"沉浸与互操作不会自动消除隐私风险","reason":"公开且难删除的记录会带来隐私治理难题，链上可追溯并不能直接推出用户隐私安全。"}]},{"q":30,"chapter":9,"section":"9.6","type":"多选","topic":"人工智能应用","title":"人工智能从感知、学习和推理支持智慧应用","trigger":"两道题从典型应用和智慧城市场景考查人工智能能力。","conclusion":"人工智能通过感知、学习、推理、预测和决策支持语音、人脸、自动驾驶与智慧城市等应用。","points":["智慧城市还会结合物联网、云计算和大数据。","自动化不必然等于人工智能，固定规则也可自动执行。","技术应用要兼顾隐私、安全、公平和人工监督。","计算机视觉、自然语言处理与围棋系统都是人工智能应用方向；“研究目标是完全取代人类”不是人工智能的标准定义。"],"boundary":"不能只凭“自动运行”或“联网设备多”就判定使用了人工智能。","id":"y2020q30","sources":[{"year":2020,"q":30,"type":"多选"},{"year":2025,"q":39,"type":"判断"},{"year":2021,"q":20,"type":"单选","page":4}],"keys":["2020-30","2025-39","2021-20"],"related":[{"id":"merged-19","label":"物联网的感知、连接与数据处理","reason":"智慧城市可由物联网采集和传输状态，再交给分析与智能服务；联网和自动化本身不足以证明用了AI。"},{"id":"y2025q20","label":"生成式人工智能能辅助多种任务，但输出必须核验","reason":"生成式AI是具体任务方向，可从输入理解、输出生成和事实核验进一步认识其能力边界。"},{"id":"y2026q45","label":"算力表示计算设备处理数据的能力","reason":"AI训练和应用依赖算力，但处理能力还受算法、数据与工程实现影响，不能只看芯片指标。"}]},{"q":30,"chapter":9,"section":"9.6","type":"多选","topic":"生成式人工智能","title":"生成式人工智能能辅助多种任务，但输出必须核验","trigger":"真题从ChatGPT应用、模型可靠性和文字润色考查生成式人工智能。","conclusion":"生成式人工智能学习数据中的模式，并根据提示生成文本、图像、音频等内容，可辅助问答、改写、翻译和编程；生成结果是否正确仍须核验。","points":["理解或识别侧重分析输入，例如判断一句话表达的情绪；生成侧重组织新输出，例如依据要点写一段通知。同一系统可以把理解与生成结合起来完成任务。","模型可能产生事实错误、过时信息、伪造出处或不安全代码。","医学等高风险内容应与权威资料和专业判断交叉验证。","例如给出“周三14点、机房301、携带学生证”三个要点，让模型写通知，再逐项核对日期、地点、要求是否保留。提供素材、明确输出要求、检查结果，可以形成可复查的辅助流程。"],"boundary":"模型名称、发布地区或能力范围都不能成为“结果完全可信”的证据。","id":"y2025q20","sources":[{"year":2024,"q":30,"type":"多选"},{"year":2025,"q":20,"type":"单选"},{"year":2025,"q":44,"type":"填空"}],"keys":["2024-30","2025-20","2025-44"],"related":[{"id":"y2026q30","label":"使用AI生成内容要核验、披露并尊重权利","reason":"人工核验之外，公开传播和特定用途还可能需要披露AI参与并尊重著作权与隐私。"},{"id":"y2024q17","label":"信息检索从需求分析到结果评价形成闭环","reason":"核验模型给出的事实或出处时，可按需求分析、资源选择、检索和结果评价的过程寻找外部证据。"}],"pointGroups":[{"title":"理解、生成与具体任务流程","indices":[0,3]},{"title":"判断输出是否可靠","indices":[1,2]}]},{"q":45,"chapter":9,"section":"9.6","type":"填空","topic":"算力","title":"算力表示计算设备处理数据的能力","trigger":"题目要求填写人工智能和数字技术发展所依赖的重要基础能力。","conclusion":"算力是计算资源执行运算和处理数据的综合能力。","points":["常见指标包括每秒运算次数、吞吐量、延迟和能效。","AI算力不仅取决于芯片，也取决于存储、网络、软件栈和集群调度。","不同任务需要不同精度与体系结构，指标不能简单横比。"],"boundary":"算力不是唯一决定因素，算法效率、数据质量和工程实现同样影响结果。","id":"y2026q45","sources":[{"year":2026,"q":45,"type":"填空"}],"keys":["2026-45"],"related":[{"id":"y2026q31","label":"GPU擅长并行计算但不能全面替代CPU","reason":"GPU适合矩阵等并行任务，CPU承担通用控制与协调，可据任务特点理解为何不能只比峰值算力。"},{"id":"y2025q1","label":"字长、主频、核心与指令速度是不同性能指标","reason":"主频、核心数和指令速率反映不同维度，不能简单相加或用单个指标代表整机处理能力。"},{"id":"y2022q33","label":"时间复杂度与空间复杂度不必同向变化","reason":"硬件能力和算法增长趋势是两层问题；提高算力不改变某算法时间、空间复杂度的定义。"}]},{"q":20,"chapter":9,"section":"9.8","type":"单选","topic":"元宇宙","title":"沉浸与互操作不会自动消除隐私风险","trigger":"题目辨析元宇宙、区块链、虚拟身份与隐私之间的关系。","conclusion":"元宇宙可结合VR/AR、数字身份、实时交互和数字资产，但技术组合不会自动解决隐私、安全和治理问题。","points":["沉浸式设备可能采集视线、动作、空间和生理等高敏感数据。","区块链的公开与难删除特性反而可能放大隐私治理难题。","身份、资产和平台互操作需要标准、权限与责任机制。"],"boundary":"“用了区块链”不等于隐私天然安全；去中心化也不等于没有运营者、规则或治理责任。","id":"y2024q20","sources":[{"year":2024,"q":20,"type":"单选"}],"keys":["2024-20"],"related":[{"id":"merged-18","label":"虚拟现实的核心特征与判断边界","reason":"先分清VR、AR的环境与交互条件，再理解沉浸式设备为何需要采集动作、空间等信息。"},{"id":"merged-17","label":"区块链结构、共识、可追溯性与信任边界","reason":"区块链的公开、可追溯和难删除特征可能放大隐私问题，不能把它当成自动保密机制。"},{"id":"y2020q20","label":"网络行为要尊重权限、署名与责任边界","reason":"数字身份与平台互操作仍受权限、来源和传播责任约束，技术上可互通不表示有权任意使用数据。"}]},{"id":"syllabus-quantum-basics","chapter":9,"section":"9.7","origin":"syllabus","topic":"考纲补充","title":"量子信息利用量子态编码和处理信息","conclusion":"经典比特通常取0或1；量子比特用量子态表示信息，可以处于叠加态。按计算基进行一次测量只得到0或1中的一个结果，不能把所有可能答案一次读出。","points":["量子计算利用量子态演化和干涉设计算法；纠缠描述多个量子系统之间不能简单拆成各自独立状态的关联。纠缠本身不允许超光速传递可控消息。","量子信息可包括量子计算、量子通信和量子测量等方向。量子计算可能帮助特定问题求解，但不会自动让每一种普通程序都更快，也不能仅凭量子比特数量比较完整性能。"],"boundary":"不要把“叠加”解释为能免费读取全部并行分支，也不要把量子计算与传统CPU主频混为一谈。","sources":[],"trigger":"依据山东省2026年专升本公共基础课考试要求补充；下方为教学示例。","related":[{"id":"y2026q45","label":"算力表示计算设备处理数据的能力","reason":"联系相邻知识理解作用范围"}]}],"sourceCount":460,"years":[2020,2021,2022,2023,2024,2025,2026]};
window.NOTE_REFERENCES={"y2026q39":[["NIST：私有云定义","https://csrc.nist.gov/glossary/term/private_cloud"],["NIST SP 800-145：五项特征与三种服务模型","https://nvlpubs.nist.gov/nistpubs/Legacy/SP/nistspecialpublication800-145.pdf"]],"merged-19":[["NIST：IoT设备的传感器/执行器与网络接口","https://csrc.nist.gov/glossary/term/iot_device"]],"y2025q20":[["NIST：生成式人工智能的内容生成定义","https://csrc.nist.gov/glossary/term/generative_artificial_intelligence"]],"syllabus-quantum-basics":[["山东省2026年专升本公共基础课考试要求","https://www.sdzk.cn/Floadup/file/20251129/6389999945835892448300421.pdf"],["IBM Quantum: Quantum computing fundamentals","https://quantum.cloud.ibm.com/learning/en/courses/quantum-business-foundations/quantum-computing-fundamentals"],["IBM Quantum: Superposition with Qiskit","https://quantum.cloud.ibm.com/learning/en/modules/quantum-mechanics/superposition-with-qiskit"]]};
window.NOTE_DEMOS={"merged-18":{"kind":"explore","title":"戴上VR前先检查三件事","task":"点击场景条件，观察它是否真正构成虚拟现实。","initial":"“有3D画面”只是可能条件，不是充分条件。","actions":[{"label":"头显＋空间定位＋实时反馈","stage":"沉浸、交互、多感知条件齐全","result":"属于典型VR体验。","tone":"good"},{"label":"普通屏幕上的3D游戏","stage":"有三维画面但沉浸条件有限","result":"不能只凭“3D”就自动判为VR。","tone":"warn"},{"label":"手机摄像头叠加虚拟家具","stage":"更接近增强现实AR","result":"真实环境仍是主要背景。","tone":"warn"},{"label":"电影院播放3D电影","stage":"立体观看但交互不足","result":"通常不作为典型VR。","tone":"bad"}]},"y2026q39":{"kind":"explore","title":"切换云资源与服务层","task":"既观察弹性资源，也分清IaaS、PaaS、SaaS交付到哪一层。","initial":"当前租用2核4GB虚拟机，通过网络使用。","actions":[{"label":"临时扩到8核16GB","stage":"无需购买新实体服务器即可调整","result":"体现弹性和按需获取资源。","tone":"good"},{"label":"IaaS：云主机","stage":"用户管理操作系统和应用","result":"服务商交付计算、存储、网络等基础资源。","tone":"good"},{"label":"PaaS：应用运行平台","stage":"用户部署代码，不必管理底层主机","result":"服务商进一步管理操作系统与运行环境。","tone":"good"},{"label":"SaaS：在线办公","stage":"用户直接使用完整软件","result":"服务商管理从基础设施到应用的整套服务。","tone":"good"},{"label":"业务结束释放实例","stage":"停止继续占用相应资源","result":"资源池可重新分配给其他用户。","tone":"good"},{"label":"远程控制一台固定电脑","stage":"不一定是云计算","result":"还要看资源池化、弹性和可度量服务。","tone":"warn"}]},"merged-19":{"kind":"sequence","title":"一条物联网数据怎样工作","task":"按从感知到服务的链路点击。","steps":[{"label":"传感器采集状态","detail":"温度、位置或设备状态成为数据。"},{"label":"网络传输数据","detail":"Wi-Fi、蜂窝网络等把数据送往处理节点。"},{"label":"边缘或云端处理","detail":"过滤、存储、分析海量连续数据。"},{"label":"应用作出反馈","detail":"告警、控制设备或生成管理决策。"}]},"y2025q18":{"kind":"explore","title":"把大数据材料放到正确的V上","task":"点击材料中的关键词，判断它强调规模、速度、多样性还是价值密度。","initial":"同一场景可能同时具有多个V，题目问的是最突出的证据。","actions":[{"label":"文本＋图片＋音频＋日志","stage":"Variety 多样性","result":"结构和格式繁多，是2023题目的直接证据。","tone":"good"},{"label":"24小时监控视频","stage":"Volume 规模","result":"持续积累形成大量数据。","tone":"warn"},{"label":"86400秒中只有12秒有用","stage":"低价值密度","result":"少量高价值线索隐藏在海量材料中。","tone":"good"},{"label":"价值密度低＝没有价值","stage":"错误","result":"占比低不等于提取出的线索价值小。","tone":"bad"}]},"y2025q40":{"kind":"explore","title":"给推荐关系做一次因果审判","task":"点击证据，判断它只能支持相关还是更接近因果。","initial":"买书A的人常常也买书B。","actions":[{"label":"共同购买记录","stage":"说明相关","result":"可用于预测，但没证明A导致B。","tone":"warn"},{"label":"相似读者偏好","stage":"可能是混杂因素","result":"共同兴趣同时影响两次购买。","tone":"good"},{"label":"随机对照推荐实验","stage":"更接近因果证据","result":"随机化有助于隔离其他因素。","tone":"good"},{"label":"推荐准确就等于找到原因","stage":"错误","result":"预测能力与因果解释不是一回事。","tone":"bad"}]},"y2020q30":{"kind":"explore","title":"识别AI应用所用能力","task":"点击应用，观察其中的感知、学习、推理或决策。","initial":"自动化不必然等于人工智能，要看实现方法。","actions":[{"label":"语音输入","stage":"语音识别＋语言处理","result":"从声音中识别文字和意图。","tone":"good"},{"label":"人脸识别","stage":"计算机视觉","result":"从图像中提取特征并进行匹配。","tone":"good"},{"label":"无人驾驶","stage":"感知＋预测＋规划＋控制","result":"多个AI模块协同工作。","tone":"good"},{"label":"固定时间开灯","stage":"可能只是预设规则","result":"自动执行本身不能证明使用了AI。","tone":"warn"}]},"y2025q20":{"kind":"explore","title":"把AI润色稿送过核验台","task":"先让模型润色，再逐项检查语言、事实和适用边界。","initial":"原句：某疗法可能改善症状。","actions":[{"label":"生成润色稿","stage":"自然语言生成","result":"模型可以改写表达。","tone":"good"},{"label":"检查是否改成“保证治愈”","stage":"发现事实夸大","result":"流畅不能替代证据。","tone":"bad"},{"label":"对照权威资料","stage":"保留可验证表述","result":"高风险内容必须核验。","tone":"good"},{"label":"直接相信模型品牌","stage":"不构成可靠性证据","result":"任何大模型都可能出错。","tone":"bad"}]},"y2026q45":{"kind":"explore","title":"同一芯片跑不同任务","task":"点击算力条件，观察为什么不能只看一个峰值数字。","initial":"算力是完成计算任务的综合能力。","actions":[{"label":"提高并行单元数量","stage":"矩阵吞吐量可能提高","result":"适合高度并行的AI和科学计算。","tone":"good"},{"label":"内存带宽不足","stage":"计算单元等待数据","result":"峰值算力高也可能发挥不出来。","tone":"warn"},{"label":"软件没有优化","stage":"硬件利用率低","result":"编译器、框架和算法同样影响实际性能。","tone":"warn"},{"label":"比较不同精度指标","stage":"结果不能直接混比","result":"FP32、FP16、INT8面向不同任务与精度需求。","tone":"good"}]},"y2024q20":{"kind":"explore","title":"检查一次沉浸式平台的数据足迹","task":"点击设备采集项，观察元宇宙为何带来新的隐私边界。","initial":"用户戴上头显并进入共享虚拟空间。","actions":[{"label":"视线与眨眼","stage":"高敏感行为数据","result":"可能推断注意、兴趣甚至部分生理状态。","tone":"warn"},{"label":"空间扫描","stage":"家庭环境数据","result":"可暴露房间布局和现实物品。","tone":"warn"},{"label":"数字资产上链","stage":"难删除且可关联","result":"公开账本不会自动保护隐私。","tone":"warn"},{"label":"用了区块链就无需治理","stage":"错误","result":"仍需权限、最小采集和责任规则。","tone":"bad"}]}};
window.NOTE_NAVIGATION={"merged-18":{"related":[{"id":"y2026q4","label":"多媒体强调集成、交互与实时处理","reason":"VR中的多感知、交互和实时反馈建立在多媒体能力上，但判断VR还须确认可交互的虚拟环境。","chapter":7},{"id":"y2024q20","label":"沉浸与互操作不会自动消除隐私风险","reason":"沉浸体验需要感知用户动作和环境，进一步查看这些数据采集为何带来隐私与治理问题。","chapter":9}],"topics":[]},"y2026q39":{"related":[{"id":"merged-19","label":"物联网的感知、连接与数据处理","reason":"物联网可把集中存储分析交给云，也可在边缘处理；云服务并不意味着全部设备数据都必须上云。","chapter":9},{"id":"y2026q45","label":"算力表示计算设备处理数据的能力","reason":"云可按需提供计算资源，但实际算力表现仍受网络、存储、软件栈和调度影响。","chapter":9}],"topics":[]},"merged-19":{"related":[{"id":"y2026q39","label":"云计算强调按需资源、资源池化、弹性与分层服务","reason":"云平台可承接集中存储和分析，服务模型与弹性说明这些资源如何按需提供和管理。","chapter":9},{"id":"y2025q18","label":"大数据的规模、速度、多样性与价值密度要按材料判断","reason":"大量传感器和联网设备可持续产生多来源数据，但是否体现大数据特征还要看规模、速度和类型。","chapter":9},{"id":"merged-13","label":"TCP/IP四层模型与OSI七层模型的对应关系","reason":"物联网三层按感知、传输和服务分工；TCP/IP分层按通信协议职责划分，两个模型不能只按层名机械对应。","chapter":6}],"topics":[]},"y2025q18":{"related":[{"id":"merged-19","label":"物联网的感知、连接与数据处理","reason":"从传感器、RFID和联网设备理解大数据的一类来源，也辨认单次识别为何不足以说明大数据。","chapter":9},{"id":"y2025q40","label":"推荐系统发现相关性不等于证明因果关系","reason":"从多来源数据提取有用模式不代表获得因果解释，规模扩大也不能自动消除偏差。","chapter":9},{"id":"y2026q12","label":"NoSQL按数据模型与访问需求选型","reason":"多样的数据与查询需求会影响数据库选型，不能仅因数据量大就默认使用某一种NoSQL产品。","chapter":10}],"topics":[]},"y2025q40":{"related":[{"id":"y2025q18","label":"大数据的规模、速度、多样性与价值密度要按材料判断","reason":"大规模多来源数据提供模式发现的材料，但有用信息占比、样本偏差与因果证据仍须分别判断。","chapter":9},{"id":"y2020q30","label":"人工智能从感知、学习和推理支持智慧应用","reason":"推荐属于学习、预测等智慧应用的语境；预测有效不等于模型已经说明现实原因。","chapter":9}],"topics":[]},"merged-17":{"related":[{"id":"merged-15","label":"加密、解密、公钥与私钥","reason":"哈希连接与数字签名承担不同工作，签名需检查私钥、公钥归属及消息完整性，不能与保密加密混同。","chapter":8},{"id":"y2024q20","label":"沉浸与互操作不会自动消除隐私风险","reason":"公开且难删除的记录会带来隐私治理难题，链上可追溯并不能直接推出用户隐私安全。","chapter":9}],"topics":[]},"y2020q30":{"related":[{"id":"merged-19","label":"物联网的感知、连接与数据处理","reason":"智慧城市可由物联网采集和传输状态，再交给分析与智能服务；联网和自动化本身不足以证明用了AI。","chapter":9},{"id":"y2025q20","label":"生成式人工智能能辅助多种任务，但输出必须核验","reason":"生成式AI是具体任务方向，可从输入理解、输出生成和事实核验进一步认识其能力边界。","chapter":9},{"id":"y2026q45","label":"算力表示计算设备处理数据的能力","reason":"AI训练和应用依赖算力，但处理能力还受算法、数据与工程实现影响，不能只看芯片指标。","chapter":9}],"topics":[]},"y2025q20":{"related":[{"id":"y2026q30","label":"使用AI生成内容要核验、披露并尊重权利","reason":"人工核验之外，公开传播和特定用途还可能需要披露AI参与并尊重著作权与隐私。","chapter":8},{"id":"y2024q17","label":"信息检索从需求分析到结果评价形成闭环","reason":"核验模型给出的事实或出处时，可按需求分析、资源选择、检索和结果评价的过程寻找外部证据。","chapter":6}],"topics":[]},"y2026q45":{"related":[{"id":"y2026q31","label":"GPU擅长并行计算但不能全面替代CPU","reason":"GPU适合矩阵等并行任务，CPU承担通用控制与协调，可据任务特点理解为何不能只比峰值算力。","chapter":1},{"id":"y2025q1","label":"字长、主频、核心与指令速度是不同性能指标","reason":"主频、核心数和指令速率反映不同维度，不能简单相加或用单个指标代表整机处理能力。","chapter":1},{"id":"y2022q33","label":"时间复杂度与空间复杂度不必同向变化","reason":"硬件能力和算法增长趋势是两层问题；提高算力不改变某算法时间、空间复杂度的定义。","chapter":11}],"topics":[]},"y2024q20":{"related":[{"id":"merged-18","label":"虚拟现实的核心特征与判断边界","reason":"先分清VR、AR的环境与交互条件，再理解沉浸式设备为何需要采集动作、空间等信息。","chapter":9},{"id":"merged-17","label":"区块链结构、共识、可追溯性与信任边界","reason":"区块链的公开、可追溯和难删除特征可能放大隐私问题，不能把它当成自动保密机制。","chapter":9},{"id":"y2020q20","label":"网络行为要尊重权限、署名与责任边界","reason":"数字身份与平台互操作仍受权限、来源和传播责任约束，技术上可互通不表示有权任意使用数据。","chapter":8}],"topics":[]},"syllabus-quantum-basics":{"related":[{"id":"y2026q45","label":"算力表示计算设备处理数据的能力","reason":"联系相邻知识理解作用范围","chapter":9}],"topics":[]}};
